# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
import pytest

from apps.accounts.models import User
from apps.accounts.services import UserService
from apps.core.enums import Role
from apps.core.exceptions import RuleViolation
from apps.placements.tests.factories import OrganizationFactory

pytestmark = pytest.mark.django_db


def test_create_student_with_profile_and_invite_email(
    django_capture_on_commit_callbacks,
    mailoutbox,
):
    with django_capture_on_commit_callbacks(execute=True):
        user = UserService.create_user(
            email="Ann@Example.com", full_name="Ann", role=Role.STUDENT, registration_number="S001"
        )
    assert user.email == "ann@example.com"
    assert user.student_profile.registration_number == "S001"
    assert user.has_usable_password()
    assert len(mailoutbox) == 1
    assert "/reset-password/" in mailoutbox[0].body


def test_student_requires_registration_number():
    with pytest.raises(RuleViolation) as error:
        UserService.create_user(email="a@example.com", full_name="A", role=Role.STUDENT)
    assert error.value.code == "registration_required"


def test_duplicate_email_is_rejected_case_insensitively():
    UserService.create_user(
        email="dup@example.com",
        full_name="D",
        role=Role.COORDINATOR,
        send_invite=False,
    )
    with pytest.raises(RuleViolation) as error:
        UserService.create_user(email="DUP@example.com", full_name="D2", role=Role.COORDINATOR)
    assert error.value.code == "email_taken"


def test_unknown_role_is_rejected():
    with pytest.raises(RuleViolation):
        UserService.create_user(email="x@example.com", full_name="X", role="WIZARD")


def test_update_user_changes_profile_fields():
    user = UserService.create_user(
        email="s@example.com",
        full_name="S",
        role=Role.STUDENT,
        registration_number="S002",
        send_invite=False,
    )
    updated = UserService.update_user(user, full_name="Sam", programme="BSc IT", year_of_study=4)
    assert updated.full_name == "Sam"
    assert updated.student_profile.programme == "BSc IT"
    assert updated.student_profile.year_of_study == 4


def test_bulk_import_reports_row_errors_without_stopping():
    csv_text = (
        "email,full_name,role,registration_number\n"
        "one@example.com,One,STUDENT,R1\n"
        "two@example.com,Two,STUDENT,R2\n"
        "bad@example.com,Bad,WIZARD,\n"
    )
    report = UserService.bulk_import(csv_text, send_invites=False)
    assert report.created == 2
    assert len(report.errors) == 1
    assert report.errors[0]["row"] == 4
    assert User.objects.filter(email="one@example.com").exists()


def test_bulk_import_requires_columns():
    with pytest.raises(RuleViolation) as error:
        UserService.bulk_import("email,role\nx@example.com,STUDENT\n")
    assert error.value.code == "bad_csv"


def test_invite_workplace_supervisor_creates_then_reuses(django_capture_on_commit_callbacks):
    organization = OrganizationFactory()
    kwargs = {
        "name": "Mentor",
        "email": "mentor@acme.example",
        "organization": organization,
        "placement_id": None,
    }
    with django_capture_on_commit_callbacks(execute=True):
        first = UserService.invite_workplace_supervisor(**kwargs)
    second = UserService.invite_workplace_supervisor(**kwargs)
    assert first.pk == second.pk
    assert first.role == Role.WORKPLACE_SUPERVISOR
    assert first.supervisor_profile.organization == organization


def test_invite_rejects_email_of_a_non_supervisor(student):
    with pytest.raises(RuleViolation):
        UserService.invite_workplace_supervisor(
            name="X", email=student.email, organization=OrganizationFactory(), placement_id=None
        )
